 // A fresh document at the saved URL exercises the actual cookie-login startup
 // ordering, with /api/dash deliberately slower than the conversation read.
 for(const draft of ['', 'Draft after reload']){
  let finishDash,withdrawn=0;const intervals=[];
  const reload=new JSDOM(fs.readFileSync(process.argv[2],'utf8'),{url:'http://127.0.0.1:21620/#chat/chat-test',runScripts:'dangerously',pretendToBeVisual:true,virtualConsole:vc,beforeParse(rw){
   rw.matchMedia=q=>({matches:process.env.DASH_UI_PHONE==='1'&&q.includes('max-width'),addEventListener(){}});rw.ResizeObserver=class{observe(){}disconnect(){}};rw.CSS={escape:x=>x};rw.scrollTo=()=>{};rw.HTMLElement.prototype.scrollIntoView=()=>{};
   rw.setInterval=(fn,ms)=>{intervals.push({fn,ms});return intervals.length};
   rw.fetch=async(url,opts={})=>{
    if(url==='/api/dash')return new Promise(resolve=>{finishDash=resolve});
    if(url==='/api/chat/chat-test')return{ok:true,status:200,json:async()=>({chat:{id:'chat-test',role:'writer'},messages:withdrawn?[]:[unanswered],busy:false})};
    if(url.endsWith('/withdraw')){withdrawn++;return withdrawReply(unanswered.content)}
    return originalFetch(url,opts);
   };
  }});
  try{
   const rw=reload.window;await tick();await tick();assert(finishDash,'cookie login did not start dashboard read');
   const button=findButton(rw.document.querySelector('#chat-msgs'),'Remove');assert(button,'fresh reload lost the withdrawal control');assert(button.disabled);button.click();assert.equal(withdrawn,0,'wrote before permissions arrived');
   rw.document.querySelector('#chat-input').value=draft;
   finishDash({ok:true,status:200,json:async()=>dash});await tick();assert(!button.disabled,'role arrival did not enable Withdraw');
   const retry=intervals.find(x=>x.ms===3000);assert(retry);retry.fn();await tick();
   if(draft){assert.equal(withdrawn,0,'automatic withdrawal replaced a draft');button.click();await tick()}
   assert.equal(withdrawn,1);assert.equal(rw.document.querySelector('#chat-input').value,unanswered.content+(draft?'\n\n'+draft:''));
   retry.fn();await tick();assert.equal(withdrawn,1,'retry repeated a completed withdrawal');
  }finally{reload.window.close()}
 }
